// Example input data for MusicGPT
return [
  {
    json: {
      prompt: "A cheerful pop song about friendship and adventure",
      music_style: "Pop",
      lyrics: "We're friends forever\nThrough every storm and weather\nTogether we'll explore\nAnd find what we're looking for"
    }
  }
];

// Process the MusicGPT response
const items = $input.all();
const processed = items.map(item => {
  const data = item.json;
  return {
    json: {
      ...data,
      message: `Music generation started! Task ID: ${data.task_id}`,
      estimated_time: `${data.eta} seconds`,
      estimated_cost: `$${data.credit_estimate}`,
      tracking_url: `https://musicgpt.com/track/${data.task_id}`
    }
  };
});

return processed;
